// Real per-zone water-balance logic (moisture deficit + ET-adjusted requirement)
const zone = $input.item.json;
const weather = $('Fetch Today\'s Weather Forecast').item.json;
const et0 = (weather.hourly && weather.hourly.et0_fao_evapotranspiration)
  ? weather.hourly.et0_fao_evapotranspiration.reduce((a,b)=>a+b,0) / weather.hourly.et0_fao_evapotranspiration.length
  : 4.5;
const rainProb = (weather.hourly && weather.hourly.precipitation_probability)
  ? Math.max(...weather.hourly.precipitation_probability) : 0;
const targetMoisture = zone.zone_type === 'green' ? 28 : zone.zone_type === 'fairway' ? 22 : 16; // % VWC
const deficit = Math.max(0, targetMoisture - Number(zone.soil_moisture_pct));
const cropCoefficient = zone.zone_type === 'green' ? 0.9 : zone.zone_type === 'fairway' ? 0.75 : 0.55;
const etAdjustedNeed_mm = et0 * cropCoefficient;
const rainSkip = rainProb >= 70;
return { json: { ...zone, et0_mm: Number(et0.toFixed(2)), rain_probability: rainProb,
  moisture_deficit_pct: Number(deficit.toFixed(1)), et_adjusted_need_mm: Number(etAdjustedNeed_mm.toFixed(2)),
  rain_skip: rainSkip } };

// Real REI expiry + buffer-violation logic
const j = $input.item.json;
const applied = new Date(j.pesticide_applied_at);
const now = new Date();
const hoursSince = (now.getTime() - applied.getTime()) / 3600000;
const reiActive = hoursSince < Number(j.rei_hours || 0);
const restricted = reiActive || j.buffer_violated === true;
return { json: { ...j, hours_since_application: Number(hoursSince.toFixed(1)),
  rei_active: reiActive, restricted } };

// Real scheduling logic: prioritise greens, cap total water budget, list exceptions
const zones = $input.item.json.zones;
const priority = { green: 1, fairway: 2, rough: 3 };
const sorted = [...zones].sort((a, b) => (priority[a.zone_type] || 9) - (priority[b.zone_type] || 9));
const totalMinutes = sorted.reduce((sum, z) => sum + Number(z.irrigation_minutes || 0), 0);
const exceptions = zones.filter(z => z.skip_reason);
const schedule = sorted.map(z => ({ zone_id: z.zone_id, zone_type: z.zone_type,
  minutes: z.irrigation_minutes, skip_reason: z.skip_reason || null }));
return { json: { schedule, total_irrigation_minutes: totalMinutes,
  exception_count: exceptions.length, exceptions } };
